import json,re
d=json.load(open('/tmp/vo.json'))
out=[]
def walk(n):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('`'+n.get('code','')+'`')
        elif t=='heading': out.append('\n## '+ (n.get('text','')) +'\n')
        elif t=='paragraph':
            for c in n.get('inlineContent',[]): walk(c)
            out.append('\n')
        elif t in ('reference','image'): pass
        for k,v in n.items():
            if k in ('inlineContent','text','code'): continue
            walk(v)
    elif isinstance(n,list):
        for i in n: walk(i)
walk(d.get('primaryContentSections'))
