python3 - <<'EOF'
import json
d=json.load(open('/tmp/vo.json'))
def render(n):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': return n.get('text','')
        if t=='codeVoice': return '`'+n.get('code','')+'`'
        if t in ('strong','emphasis','link','reference','inlineHead'):
            s=''.join(render(c) for c in n.get('inlineContent',[]))
            return ('**'+s+'**') if t=='strong' else s
        if t=='paragraph': return ''.join(render(c) for c in n.get('inlineContent',[]))+'\n'
        if t=='heading': return '\n## '+n.get('text','')+'\n'
        return ''.join(render(v) for v in n.values() if isinstance(v,(list,dict)))
    if isinstance(n,list): return ''.join(render(i) for i in n)
    return ''
txt=render(d.get('primaryContentSections'))
for line in txt.split('\n'):
    if 'rotor' in line.lower() or 'braille' in line.lower(): print(repr(line))
EOF
